    # -- Wcluster.new {
    def new(self):
        # Connect destroy signal to ensure tabs are deselected when window closes
        self.get_widget("wCluster").connect("destroy", self.on_wCluster_destroy)

        self.treeHosts = self.get_widget("treeHosts")
